"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Dezember 2024                #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Dezember 2024                #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during December 2025\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 10 Dezember 2024\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Tesla Battery Cooling${NC}\n-------------------------------------------------------------------------------\nThis project was initiatied by Alexander Sadowski who is an unique expert with\nthe Open Source project FreeCAD.\n\nCredit to him, that the OpenFOAM community got a new OpenFOAM tutorial based\non his initiation.\n\nThe case provides interesting insights but is not perfect correct in terms of\nmeshing and pyhsical approximation.\\n\\n\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"`\n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/T': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    object      T;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 1 0 0 0];\n\ninternalField   uniform 293;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            zeroGradient;\n    }\n\n    // The boundary condition for the batteries would be specifed by the\n    // entry above (wall -> group). But in OpenFOAM the patches/groups\n    // are read from the bottom. Hence, the entry which comes later wins.\n    // If one would put the below given BC above the "wall" definition, it will\n    // not be recognized since the patch is already initialized with the \n    // definition given above\n    // 100W per battery = 20 batteries x 100W = 2000 W\n    tesla-4680Battery\n    {\n        type            externalTemperature;\n        Q               constant 2000;\n        value           $internalField;\n    }\n\n    inlet\n    {\n        type            fixedValue;\n        value           $internalField;\n    }\n\n    outlet\n    {\n        type            inletOutlet;\n        value           $internalField;\n\n        // If recirculation occurs, we put a higher temperature back to the\n        // domain compared to the inlet one (just as an example - no \n        // physical meaning behind that)\n        inletValue      uniform 300;\n    }\n}\n\n// ************************************************************************* //\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volVectorField;\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 0 0);\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            noSlip;\n    }\n\n    inlet\n    {\n        type                flowRateInletVelocity;\n\n        // Volumetric flow rate (arbitrary)\n        // We assume 100 m^3/h\n        volumetricFlowRate  constant 0.0277;          // Arbitrary\n    }\n\n    outlet\n    {\n        type            pressureInletOutletVelocity;\n        value           uniform (0 0 0);\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/alphat': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      alphat;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [1 -1 -1 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            compressible::alphatWallFunction;\n        Prt             0.85;\n        value           uniform 0;\n    }\n    inlet\n    {\n        type            calculated;\n        value           uniform 0;\n    }\n    outlet\n    {\n        type            calculated;\n        value           uniform 0;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/epsilon': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      epsilon;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -3 0 0 0 0];\n\ninternalField   uniform 200;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            epsilonWallFunction;\n        value           uniform 200;\n    }\n    inlet\n    {\n        type            turbulentMixingLengthDissipationRateInlet;\n\n        // Area Inlet       0.032 m^2\n        // Circumference    0.24  m\n        // Hyd. diam.       0.533 m\n        // MixingLength     0.038\n        mixingLength    0.020254;\n        value           uniform 200;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 200;\n        value           uniform 200;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/k': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      k;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -2 0 0 0 0];\n\ninternalField   uniform 1;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            kqRWallFunction;\n        value           uniform 1;\n    }\n    inlet\n    {\n        type            turbulentIntensityKineticEnergyInlet;\n\n        // This is just a guess and not of physical correctness\n        intensity       0.03;\n        value           uniform 1;\n    }\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 1;\n        value           uniform 1;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/nut': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      nut;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -1 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            nutkWallFunction;\n        value           uniform 0;\n    }\n    inlet\n    {\n        type            calculated;\n        value           uniform 0;\n    }\n    outlet\n    {\n        type            calculated;\n        value           uniform 0;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/p': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       volScalarField;\n    object      p;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [1 -1 -2 0 0 0 0];\n\ninternalField   uniform 110000;\n\nboundaryField\n{\n    // Need to be included because the boundary files are copied after the\n    // decomposition was started. Thus, the boundary conditions of any field\n    // does not include special BC which are introduced when we split a mesh\n    // such as processor boundary. To avoid issues, we include the basic-\n    // generic boundary condition file\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    // This is a group that includes the batteries and channel wall\n    // We can also specify single patch definition or merge them into groups\n    // and only everything with one entry\n    wall\n    {\n        type            zeroGradient;\n    }\n    inlet\n    {\n        type            zeroGradient;\n    }\n    outlet\n    {\n        type            fixedValue;\n        value           uniform 110000;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: April 2016                      #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf 0 log* system/decomposeParDict\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/momentumTransport': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      momentumTransport;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType  RAS;\n\nRAS\n{\n    model           kEpsilon;\n\n    turbulence      on;\n\n    printCoeffs     on;\n}\n\n\n// ************************************************************************* //\n',
    'constant/physicalProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      physicalProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nthermoType\n{\n    type            heRhoThermo;\n    mixture         pureMixture;\n    transport       const;\n    thermo          hConst;\n    equationOfState perfectGas;\n    specie          specie;\n    energy          sensibleEnthalpy;\n}\n\nmixture\n{\n    specie\n    {\n        molWeight   28.9;\n    }\n    thermodynamics\n    {\n        Cp          1005;\n        hf          0;\n    }\n    transport\n    {\n        mu          1.82e-05;\n        Pr          0.71;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  10 Dezember 2024                   #\n#-------------------------------------------------#\n# Topic:       Complex geometry meshing           #\n# OpenFOAM:    version 12 (Foundation)            #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\nif [ -f cad/backgroundMesh.unv ];\nthen\n    echo "   - Background mesh exist, proceed..."\nelse\n    echo "   - No background mesh exist, please create one\'"\n    echo ""\n    exit\nfi\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv > logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Decompose mesh to 8 cores"\ncp system/decomposeParDictHierarchical system/decomposeParDict\ndecomposePar >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh (~ 5 minutes)"\nmpirun -np 8 snappyHexMesh -overwrite -parallel >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Scale the mesh down to correct size"\nmpirun -np 8 transformPoints "scale=(0.001 0.001 0.001)" -parallel >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\n"\n\n#------------------------------------------------------------------------------\necho -e "   - Redistribute the mesh for better proc-communication"\ncp system/decomposeParDictScotch system/decomposeParDict\nrm -rf proc*/0\nmpirun -np 8 redistributePar -overwrite -parallel >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Renumber mesh for speedup (~5-15%)"\nmpirun -np 8 renumberMesh -overwrite -parallel >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Copy 0.orig to processor*/0"\nfor i in $(ls -d processor*)\ndo\n    rm -r ${i}/0\n    cp -r 0.orig ${i}/0\ndone\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start steadyState calculation (1h)"\nmpirun -np 8 foamRun -parallel >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Simulation ended\\n\\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          fluid; \n\nstartFrom       latestTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         100;\n\ndeltaT          1;\n\nwriteControl    runTime;\n\nwriteInterval   10;\n\npurgeWrite      0;\n\nwriteFormat     binary;\n\nwritePrecision  8;\n\nwriteCompression off;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\n\n// ************************************************************************* //\n',
    'system/decomposeParDictHierarchical': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      decomposeParDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nnumberOfSubdomains  8;\n\n/*\n    Main methods are:\n    1) Geometric: "simple"; "hierarchical", with ordered sorting, e.g. xyz, yxz\n    2) Scotch: "scotch", when running in serial; "ptscotch", running in parallel\n*/\n\nmethod              hierarchical;\n\nsimpleCoeffs\n{\n    n               (4 2 1); // total must match numberOfSubdomains\n    delta           0.001;\n}\n\nhierarchicalCoeffs\n{\n    n               (2 2 2); // total must match numberOfSubdomains\n    delta           0.001;\n    order           xyz;\n}\n\n\n// ************************************************************************* //\n',
    'system/decomposeParDictScotch': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      decomposeParDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nnumberOfSubdomains  8;\n\nmethod              scotch;\n\n\n// ************************************************************************* //\n',
    'system/fvConstraints': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    object      fvConstraints;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n/*limitp\n{\n    type       limitPressure;\n\n    minFactor  0.1;\n    maxFactor  2;\n}\n*/\n\nlimitT\n{\n    type        limitTemperature;\n    min         295;\n    max         400;\n    select      all;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default             steadyState;\n}\n\ngradSchemes\n{\n    default             Gauss linear;\n}\n\ndivSchemes\n{\n    default             none;\n\n    div(phi,U)          bounded Gauss upwind;\n    div(phi,h)          bounded Gauss upwind;\n\n    div(phi,epsilon)    bounded Gauss upwind;\n    div(phi,k)          bounded Gauss upwind;\n\n    div(phi,K)          bounded Gauss upwind;\n\n    div(phid,p)         Gauss upwind;\n\n    div(((rho*nuEff)*dev2(T(grad(U)))))      Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    p\n    {\n        solver          GAMG;\n        smoother        DICGaussSeidel;\n\n        tolerance       1e-08;\n        relTol          0.1;\n    }\n\n    "(U|h|k|epsilon)"\n    {\n        solver          PBiCGStab;\n        preconditioner  DILU;\n\n        tolerance       1e-08;\n        relTol          0.1;\n    }\n}\n\nPIMPLE\n{\n    nNonOrthogonalCorrectors 1;\n    nCorrectors 2;\n\n    transonic       no;\n    consistent      yes;\n\n    residualControl\n    {\n        p               1e-3;\n        U               1e-4;\n        h               1e-3;\n        "(k|epsilon)"   1e-3;\n    }\n}\n\nrelaxationFactors\n{\n    fields\n    {\n        p               1;\n    }\n\n    equations\n    {\n        p               1;\n        U               0.8;\n        h               0.8;\n        k               0.7;\n        epsilon         0.7;\n    }\n}\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\n//- minFaceWeight (0 -> 0.5)\n// minFaceWeight 0.02;\n// maxNonOrtho 84;\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh   true;\nsnap              true;\naddLayers         true;\n\ngeometry\n{\n    geometry\t\n\t{\n        file "regionSTL.stl";\n\t\ttype triSurfaceMesh;\n\t\tregions\n\t\t{\n\t\t\tchannel { name channel; };\n\t\t\tinlet { name inlet; };\n\t\t\toutlet { name outlet; };\n\t\t\ttesla-4680Battery { name tesla-4680Battery; };\n\t\t}\n\t}\n};\n\ncastellatedMeshControls\n{\n    maxLocalCells 8000000;\n    maxGlobalCells 2000000;\n    minRefinementCells 0;\n    maxLoadUnbalance 0.20;\n    nCellsBetweenLevels 4;\n\n    features\n    (\n    );\n\n    refinementSurfaces\n    {\n\t\tgeometry\n\t\t{\n\t\t\tlevel (0 0);\n\t\t\tregions\n\t\t\t{\n\t\t\t\tchannel { level (0 0); patchInfo { type wall; }};\n\t\t\t\tinlet { level (0 0); patchInfo { type patch; }};\n\t\t\t\toutlet { level (0 0); patchInfo { type patch; }};\n\t\t\t\ttesla-4680Battery { level (2 2); patchInfo { type wall; }};\n\t\t\t}\n\t\t}\n    }\n\n    refinementRegions\n    {\n    }\n\n    // Resolve sharp angles\n    resolveFeatureAngle 30;\n\n    locationInMesh (0 0 -5);\n\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n    tolerance 1.2;\n    nSolveIter 200;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 4;\n\n    // Feature snapping\n\n        nFeatureSnapIter 5;\n        implicitFeatureSnap true;\n        explicitFeatureSnap false;\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    relativeSizes true;\n\n    layers\n    {\n\t\ttesla-4680Battery \n        { \n            nSurfaceLayers 2;\n        };\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.4;\n    finalLayerThickness 0.6;\n    minThickness 0.0001;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    // Note: changed(corrected) w.r.t 17x! (didn\'t do anything in 17x)\n    nGrow 0;\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 85;\n\n    // At non-patched sides allow mesh to slip if extrusion direction makes\n    // angle larger than slipFeatureAngle.\n    slipFeatureAngle 25;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 4;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.2;\n\n    // Angle used to pick up medial axis points\n    // Note: changed(corrected) w.r.t 17x! 90 degrees corresponds to 130 in 17x.\n    minMedianAxisAngle 90;\n\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n}\n\nmeshQualityControls\n{\n    #include "meshQualityDict"\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Write flags\nwriteFlags\n(\n    scalarLevels\n    layerSets\n    layerFields     // write volScalarField for layer coverage\n);\n\n\nmergeTolerance 1e-6;\n\n\n// ************************************************************************* //\n',
}
